head.script:
scwin.screenId = "jldinf92000";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_modCnt", fn: function(){ return ((dma_reqCkMap.get("modCnt") ?? (() => { throw new Error("unresolved:" + "reqCkMap.modCnt"); })()) > 0); } }, { id: "if_delCnt", fn: function(){ return ((dma_reqCkMap.get("delCnt") ?? (() => { throw new Error("unresolved:" + "reqCkMap.delCnt"); })()) > 0); } }, { id: "if_activYn", fn: function(){ return ((dma_map.get("activYn") ?? (() => { throw new Error("unresolved:" + "map.activYn"); })()) === 'Y' && (dma_map.get("activTpCd") ?? (() => { throw new Error("unresolved:" + "map.activTpCd"); })()) === 'Y' && (dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) !== 'Y' && (dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) !== 'D'); } }, { id: "if_activYn", fn: function(){ return ((dma_reqCkMap.get("delCnt") ?? (() => { throw new Error("unresolved:" + "reqCkMap.delCnt"); })()) == 0  && (dma_reqCkMap.get("modCnt") ?? (() => { throw new Error("unresolved:" + "reqCkMap.modCnt"); })()) == 0 && (dma_map.get("delYn") ?? (() => { throw new Error("unresolved:" + "map.delYn"); })()) !== 'Y'); } }, { id: "if_modCnt", fn: function(){ return (!(String(((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })())) == null ? '' : ((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()))).length === 0) && (dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()) === (dma_map.get("isurCd") ?? (() => { throw new Error("unresolved:" + "map.isurCd"); })())); } }, { id: "if_delCnt", fn: function(){ return (!(String(((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })())) == null ? '' : ((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()))).length === 0) && (dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()) === (dma_map.get("isurCd") ?? (() => { throw new Error("unresolved:" + "map.isurCd"); })())); } }, { id: "if_activYn", fn: function(){ return (!(String(((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })())) == null ? '' : ((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()))).length === 0) && (dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()) === (dma_map.get("isurCd") ?? (() => { throw new Error("unresolved:" + "map.isurCd"); })())); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_stdcdType", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("stdcdType"))); } },
        { childId: "ipt_stdCd", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("stdCd"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.setComma();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf92000.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf92000.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_goModify_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_goModify_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_goModify_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.go_modify()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf92000.btn_goModify_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_goDelete_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_goDelete_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_goDelete_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.go_delete()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf92000.btn_goDelete_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_self_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_self_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_self_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.win.closePopup()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf92000.btn_self_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.setComma
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.setComma = function () {
    /* sdd-asis-lifecycle:begin setComma — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.num.formatNumber($('#ipt_expPayAmt')[0]);
    $c.num.formatNumber($('#ipt_dcSales')[0]);
    $c.util.getComponent('txt_expPayAmtTd').setLabel($c.util.getComponent('ipt_expPayAmt').getValue());
    $c.util.getComponent('txt_dcSalesTd').setLabel($c.util.getComponent('ipt_dcSales').getValue());
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.open_modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.open_modify = function () {
    /* sdd-asis-lifecycle:begin open_modify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const stdcdType = $c.util.getComponent('ipt_stdcdType').getValue();
    const stdCd = $c.util.getComponent('ipt_stdCd').getValue();
    const form = (document.JLDINF92000 || { elements: [] });
    $c.util.getComponent('ipt_modDelCd').setValue("mod");
    fn_passwordWin(form);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.open_delete
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.open_delete = function () {
    /* sdd-asis-lifecycle:begin open_delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const stdcdType = $c.util.getComponent('ipt_stdcdType').getValue();
    const stdCd = $c.util.getComponent('ipt_stdCd').getValue();
    const form = (document.JLDINF92000 || { elements: [] });
    $c.util.getComponent('ipt_modDelCd').setValue("del");
    fn_passwordWin(form);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.go_modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.go_modify = async function () {
    /* sdd-asis-lifecycle:begin go_modify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.JLDINF92000 || { elements: [] });
    const url = "/stdcd/stdcdModify.do?method=stdcdModify&type=7&std_cd=" + $c.util.getComponent('ipt_stdCd').getValue();
    fm.action = url;
    fm.target = "_top";
    await moveUrl(url, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.go_delete
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.go_delete = function () {
    /* sdd-asis-lifecycle:begin go_delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const stdcdType = $c.util.getComponent('ipt_stdcdType').getValue();
    const stdCd = $c.util.getComponent('ipt_stdCd').getValue();
    const form = (document.JLDINF92000 || { elements: [] });
    fn_stdCdDelWin(form);
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};
